/// ### What it does
/// Detects syntax that looks like a footnote reference.
///
/// Rustdoc footnotes are compatible with GitHub-Flavored Markdown (GFM).
/// GFM does not parse a footnote reference unless its definition also
/// exists. This lint checks for footnote references with missing
/// definitions, unless it thinks you're writing a regex.
///
/// ### Why is this bad?
/// This probably means that a footnote was meant to exist,
/// but was not written.
///
/// ### Example
/// ```no_run
/// /// This is not a footnote[^1], because no definition exists.
/// fn my_fn() {}
/// ```
/// Use instead:
/// ```no_run
/// /// This is a footnote[^1].
/// ///
/// /// [^1]: defined here
/// fn my_fn() {}
/// ```
// #[clippy::version = "1.89.0"]
export const DOC_SUSPICIOUS_FOOTNOTES: Lint = Object.freeze<Lint>({
  name: "clippy::DOC_SUSPICIOUS_FOOTNOTES",
  default_level: "Warn",
  desc: "looks like a link or footnote ref, but with no definition",
  edition_lint_opts: undefined,
  report_in_external_macro: true,
  future_incompatible: undefined,
  is_externally_loaded: true,
  feature_gate: undefined,
  crate_level_only: false,
  eval_always: false,
  ignore_deny_warnings: false,
  rust_version: undefined,
});
